function escapeHtml(s){return String(s==null?"":s).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c];});}
function num(n){var v=Number(String(n).replace(",","."));return Number.isFinite(v)?Math.min(100000000,Math.max(0,v)):0;}
function money(n){return new Intl.NumberFormat(lang==="ru"?"ru-RU":"lv-LV",{style:"currency",currency:"EUR",minimumFractionDigits:2,maximumFractionDigits:2}).format(n||0);}
function shortMoney(n){return new Intl.NumberFormat(lang==="ru"?"ru-RU":"lv-LV",{maximumFractionDigits:2}).format(n);}
function getItemName(item){return lang==="ru"?item.ru:item.lv;}
function getCat(id){return cats.find(function(c){return c.id===id;})||cats[0];}
function toast(msg){var node=$("toast");node.textContent=msg;node.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(function(){node.classList.remove("show");},3200);}
function safeGet(k){try{return localStorage.getItem(k);}catch(e){return null;}}
function safeSet(k,v){try{localStorage.setItem(k,v);return true;}catch(e){return false;}}
var PRO_KEYS=[["contractor",160],["registration",80],["contact",160],["address",200],["clientAddress",200],["bank",120],["validUntil",10],["duration",120],["payment",600],["scope",1200]];var PRO_TEMPLATE="cenaradar-pro-contractor-v1";
function defaultPro(){var p={advance:0,signatures:true,logo:""};PRO_KEYS.forEach(function(k){p[k[0]]="";});return p;}
function cleanPro(p){var out=defaultPro();p=p&&typeof p==="object"?p:{};PRO_KEYS.forEach(function(k){out[k[0]]=String(p[k[0]]||"").slice(0,k[1]);});out.advance=Math.min(100,num(p.advance));out.signatures=p.signatures!==false;out.logo=typeof p.logo==="string"&&p.logo.length<=180000&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(p.logo)?p.logo:"";return out;}
function proAmounts(){var total=getTotals().total,advance=Math.round(total*fields.pro.advance)/100;return {advance:advance,balance:Math.round((total-advance)*100)/100};}
function refreshLogo(){var box=$("pro-logo-preview");box.textContent="";if(fields.pro.logo){var img=document.createElement("img");img.src=fields.pro.logo;img.alt=t("proLogo");box.appendChild(img);}else box.textContent=t("proLogoNone");$("pro-logo-remove").disabled=!fields.pro.logo;}
function fillPro(){PRO_KEYS.forEach(function(k){$("pro-"+k[0]).value=fields.pro[k[0]];});$("pro-advance").value=fields.pro.advance;$("pro-signatures").checked=fields.pro.signatures;refreshLogo();}
function updatePro(){PRO_KEYS.forEach(function(k){fields.pro[k[0]]=$("pro-"+k[0]).value.slice(0,k[1]);});fields.pro.advance=Math.min(100,num($("pro-advance").value));fields.pro.signatures=$("pro-signatures").checked;renderSummary();persist();}
function loadLogo(file){if(!file)return;if(!["image/png","image/jpeg","image/webp"].includes(file.type)||file.size>2000000){toast(t("proLogoError"));return;}var reader=new FileReader();reader.onerror=function(){toast(t("proLogoError"));};reader.onload=function(){var img=new Image();img.onerror=function(){toast(t("proLogoError"));};img.onload=function(){try{var canvas=document.createElement("canvas"),ratio=Math.min(1,360/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*ratio));canvas.height=Math.max(1,Math.round(img.height*ratio));var ctx=canvas.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);var value=canvas.toDataURL("image/jpeg",.72);if(value.length>180000)throw Error("logo");fields.pro.logo=value;refreshLogo();persist();toast(t("proLogoReady"));}catch(e){toast(t("proLogoError"));}};img.src=String(reader.result);};reader.readAsDataURL(file);}
function saveProTemplate(){var p=fields.pro,copy={contractor:p.contractor,registration:p.registration,contact:p.contact,address:p.address,bank:p.bank,logo:p.logo};toast(safeSet(PRO_TEMPLATE,JSON.stringify(copy))?t("proTemplateSaved"):t("saveError"));}
function useProTemplate(){try{var p=JSON.parse(safeGet(PRO_TEMPLATE)||"null");if(!p){toast(t("proTemplateEmpty"));return;}var clean=cleanPro(p);["contractor","registration","contact","address","bank","logo"].forEach(function(k){fields.pro[k]=clean[k];});fillPro();persist();toast(t("proTemplateLoaded"));}catch(e){toast(t("proTemplateEmpty"));}}
function proText(){var p=fields.pro,a=proAmounts(),out=[];PRO_KEYS.forEach(function(k){if(p[k[0]])out.push(t("pro_"+k[0])+": "+p[k[0]]);});if(p.advance)out.push(t("proAdvanceAmount")+" ("+p.advance+"%): "+money(a.advance),t("proBalance")+": "+money(a.balance));return out;}
function proHtml(){var p=fields.pro,keys=PRO_KEYS.filter(function(k){return !!p[k[0]];});return keys.length?'<div class="pro-print-details">'+keys.map(function(k){return '<div><strong>'+escapeHtml(t("pro_"+k[0]))+'</strong><span>'+escapeHtml(p[k[0]])+'</span></div>';}).join("")+'</div>':"";}
function proPaymentHtml(){var p=fields.pro,a=proAmounts();return p.advance?'<div class="pro-print-payment"><div><span>'+escapeHtml(t("proAdvanceAmount"))+' ('+p.advance+'%)</span><b>'+escapeHtml(money(a.advance))+'</b></div><div><span>'+escapeHtml(t("proBalance"))+'</span><b>'+escapeHtml(money(a.balance))+'</b></div></div>':"";}
function signatureHtml(){return fields.pro.signatures?'<div class="pro-signatures"><div>'+escapeHtml(t("proContractorSign"))+'<span></span></div><div>'+escapeHtml(t("proClientSign"))+'<span></span></div></div>':"";}
