function updateRoom(){var v=roomValues();$("room-error").classList.toggle("hidden",!!v);$("room-add").disabled=!v;var results={"floor":["floor","m²"],"walls":["walls","m²"],"skirting":["skirting","m"],"buy-floor":["buyFloor","m²"],"paint":["paint","l"],"paint-ceiling":["paintCeiling","l"]};Object.keys(results).forEach(function(k){var pair=results[k];$("room-"+k).textContent=v?shortMoney(Math.round(v[pair[0]]*100)/100)+" "+pair[1]:"—";});}
function addRoomWork(){var v=roomValues(),id=$("room-work").value;if(!v)return;var k=["paint-walls","putty-walls","tile-wall"].includes(id)?"walls":id==="floor-skirting"?"skirting":"floor";if(v[k]<=0)return; if(!appendWork(id))return;lines[lines.length-1].qty=Math.round(v[k]*100)/100;if(fields.activeRoom){var r=fields.rooms.find(function(x){return x.id===fields.activeRoom;});if(r)r.dims=ROOM_DIM_KEYS.map(function(k){return Number($("room-"+k).value);});}roomFilter="all";renderRoomControls();renderLines();persist();toast(t("roomAdded"));}
function renderLines(){var tbody=$("estimate-lines");tbody.innerHTML=lines.filter(function(l){return roomFilter==="all"||(l.roomId||"")===roomFilter;}).map(function(l){return '<tr data-uid="'+escapeHtml(l.uid)+'"><td><input class="line-input name-input" data-field="name" aria-label="'+escapeHtml(t("work"))+'" value="'+escapeHtml(l.name)+'"><input class="line-input unit-input" data-field="unit" aria-label="'+escapeHtml(t("unit"))+'" value="'+escapeHtml(l.unit)+'" maxlength="15" list="unit-options"><select class="line-room-select" data-field="roomId" aria-label="'+escapeHtml(t("roomGroup"))+'">'+roomOptions(l.roomId||"",false)+'</select></td><td data-label="'+escapeHtml(t("qty"))+'"><input class="line-input" type="number" inputmode="decimal" min="0" step="0.01" data-field="qty" aria-label="'+escapeHtml(t("qty"))+'" value="'+escapeHtml(l.qty)+'"></td><td data-label="'+escapeHtml(t("labor"))+'"><input class="line-input" type="number" inputmode="decimal" min="0" step="0.01" data-field="labor" aria-label="'+escapeHtml(t("labor"))+'" value="'+escapeHtml(l.labor)+'"></td><td data-label="'+escapeHtml(t("materials"))+'"><input class="line-input" type="number" inputmode="decimal" min="0" step="0.01" data-field="material" aria-label="'+escapeHtml(t("materials"))+'" value="'+escapeHtml(l.material)+'"></td><td class="sum-value" data-label="'+escapeHtml(t("sum"))+'">'+money(l.qty*(l.labor+l.material))+'</td><td><button type="button" class="remove-line" data-remove="'+escapeHtml(l.uid)+'" title="'+escapeHtml(t("delete"))+'" aria-label="'+escapeHtml(t("delete"))+'">×</button></td></tr>';}).join("");renderSummary();}
function chosenPrice(w){return w.min===null?0:priceMode==="min"?w.min:priceMode==="max"?w.max:Math.round((w.min+w.max)/2*100)/100;}
function appendWork(workId){var w=works.find(function(item){return item.id===workId;});if(!w)return false;lines.push({uid:Date.now()+"-"+Math.random().toString(16).slice(2),workId:w.id,name:getItemName(w),unit:w.unit,qty:1,labor:chosenPrice(w),material:0,roomId:fields.activeRoom});return true;}
function addWork(workId){if(!appendWork(workId))return;roomFilter="all";renderRoomControls();renderLines();persist();var w=works.find(function(x){return x.id===workId;});toast(t(w&&w.min===null?"quoteAdded":"added"));}
var TEMPLATES={bath:["demo-tiles","floor-waterproof","tile-wall","tile-floor","pl-wc","pl-basin","pl-faucet"],walls:["prime-walls","putty-walls","sand-walls","paint-walls"],floor:["demo-floor","floor-self","floor-laminate","floor-skirting"]};
function applyTemplate(key){var items=TEMPLATES[key];if(!items)return;items.forEach(appendWork);roomFilter="all";renderRoomControls();renderLines();persist();toast(t("templateAdded"));}
function addCustom(){roomFilter="all";renderRoomControls();lines.push({uid:Date.now()+"-"+Math.random().toString(16).slice(2),workId:"",name:t("custom"),unit:"gab.",qty:1,labor:0,material:0,roomId:fields.activeRoom});renderLines();persist();var inputs=$("estimate-lines").querySelectorAll(".name-input");if(inputs.length)inputs[inputs.length-1].focus();}
function changeLine(el){var row=el.closest("tr[data-uid]");if(!row)return;var line=lines.find(function(l){return l.uid===row.getAttribute("data-uid");});if(!line)return;var field=el.getAttribute("data-field");if(!["name","unit","qty","labor","material","roomId"].includes(field))return;if(field==="roomId"){line.roomId=fields.rooms.some(function(r){return r.id===el.value;})?el.value:"";renderLines();persist();return;}line[field]=field==="name"?el.value.slice(0,220):field==="unit"?el.value.slice(0,15):num(el.value);row.querySelector(".sum-value").textContent=money(num(line.qty)*(num(line.labor)+num(line.material)));renderSummary();persist();}
function updateField(){fields.project=$("project-name").value.slice(0,200);fields.client=$("client-name").value.slice(0,200);fields.date=$("estimate-date").value;fields.number=$("estimate-number").value.slice(0,50);fields.notes=$("estimate-notes").value.slice(0,3000);fields.reserve=Math.min(100,num($("reserve").value));fields.vat=$("vat-toggle").checked;renderSummary();persist();}
function resetEstimate(){if(lines.length&&!confirm(t("confirmNew")))return;currentId=null;lines=[];fields=defaultFields();fillFields();renderLines();persist();toast(t("newEstimate"));}
function getSaved(){try{var a=JSON.parse(safeGet(SAVED)||"[]");return Array.isArray(a)?a:[];}catch(e){return [];}}
function saveEstimate(){var a=getSaved();if(!currentId)currentId="est-"+Date.now();var state=snapshot(),idx=a.findIndex(function(s){return s.id===currentId;});if(idx<0)a.unshift(state);else a[idx]=state;a.sort(function(x,y){return String(y.updated).localeCompare(String(x.updated));});if(!safeSet(SAVED,JSON.stringify(a.slice(0,60))))toast(t("saveError"));else toast(t("saved"));persist();}
function showSaved(){var a=getSaved(),el=$("saved-list");el.innerHTML=a.length?a.map(function(s){var name=(s.fields&&s.fields.project)||t("noName");return '<div class="saved-row"><div><strong>'+escapeHtml(name)+'</strong><span>'+escapeHtml((s.fields&&s.fields.date)||"")+" · "+(s.lines||[]).length+' '+escapeHtml(t("totalWork"))+'</span></div><div style="display:flex;gap:6px"><button type="button" data-load="'+escapeHtml(s.id)+'">'+escapeHtml(t("open"))+'</button><button class="delete-saved" type="button" data-delete-saved="'+escapeHtml(s.id)+'">×</button></div></div>';}).join(""):'<div class="no-saved">'+escapeHtml(t("noSaved"))+'</div>';$("saved-modal").classList.remove("hidden");}
function closeSaved(){$("saved-modal").classList.add("hidden");}
function loadSaved(id){var s=getSaved().find(function(row){return row.id===id;});if(!s)return;try{var n=normalizeSnapshot(s);currentId=n.id;fields=n.fields;lines=n.lines;fillFields();renderLines();persist();closeSaved();$("estimate").scrollIntoView({behavior:"smooth"});}catch(e){toast(t("invalidFile"));}}
function deleteSaved(id){var a=getSaved().filter(function(x){return x.id!==id;});safeSet(SAVED,JSON.stringify(a));showSaved();}
function download(name,content,type){var blob=new Blob([content],{type:type||"application/octet-stream"});var url=URL.createObjectURL(blob);var a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},1000);}
function filename(){return (fields.project||"cenaradar-tame").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-zA-Z0-9_-]+/g,"-").slice(0,45).replace(/^-|-$/g,"")||"cenaradar-tame";}
function exportFile(){if(!lines.length){toast(t("emptyEstimate"));return;}download(filename()+".json",JSON.stringify(snapshot(),null,2),"application/json;charset=utf-8");toast(t("fileDownloaded"));}
function csvCell(v){var s=String(v==null?"":v);if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportCsv(){if(!checkExport())return;var x=getTotals();var rows=[[t("titleDoc"),fields.project||t("noName")],[t("clientName"),fields.client],[t("estimateDate"),fields.date],[t("estimateNr"),fields.number],[],[t("work"),t("unit"),t("qty"),t("labor"),t("materials"),t("sum"),t("roomGroup")]];function dec(n){return Number(n).toFixed(2).replace(".",",");}
lines.forEach(function(l){rows.push([l.name,l.unit,dec(l.qty),dec(l.labor),dec(l.material),dec(l.qty*(l.labor+l.material)),roomName(l.roomId)]);});if(fields.rooms.length){rows.push([],[t("roomBreakdown"),t("roomBeforeTax")]);roomTotals().forEach(function(r){rows.push([r.name,dec(r.total)]);});}PRO_KEYS.forEach(function(k){if(fields.pro[k[0]])rows.push([t("pro_"+k[0]),fields.pro[k[0]]]);});var pa=proAmounts();if(fields.pro.advance)rows.push([t("proAdvanceAmount"),dec(pa.advance)],[t("proBalance"),dec(pa.balance)]);rows.push([],[t("laborCost"),dec(x.labor)],[t("materialCost"),dec(x.material)],[t("subtotal"),dec(x.subtotal)],[t("reserveSum")+" ("+fields.reserve+"%)",dec(x.reserve)],["PVN",dec(x.vat)],[t("total"),dec(x.total)],[t("estimateNotes"),fields.notes]);download(filename()+".csv","\uFEFF"+rows.map(function(r){return r.map(csvCell).join(";");}).join("\r\n"),"text/csv;charset=utf-8");toast(t("fileDownloaded"));}
function getReportText(){var x=getTotals();var out=[t("titleDoc")+" / CenaRadar",fields.project||t("noName"),t("clientName")+": "+(fields.client||"—"),t("estimateDate")+": "+fields.date,"№ "+fields.number,""];
lines.forEach(function(l,i){out.push((i+1)+". "+(fields.rooms.length?"["+roomName(l.roomId)+"] ":"")+l.name+" — "+l.qty+" "+l.unit+" × ("+money(l.labor)+" + "+money(l.material)+") = "+money(l.qty*(l.labor+l.material)));});
if(fields.rooms.length){out.push("",t("roomBreakdown")+" ("+t("roomBeforeTax")+")");roomTotals().forEach(function(r){out.push(r.name+": "+money(r.total));});}out.push.apply(out,[""].concat(proText()));if(hasMissingPrice())out.push("",t("quoteWarning"));out.push("",t("laborCost")+": "+money(x.labor),t("materialCost")+": "+money(x.material),t("reserveSum")+" ("+fields.reserve+"%): "+money(x.reserve),"PVN: "+money(x.vat),t("total")+": "+money(x.total),"",fields.notes||"",t("footerDoc"),"https://cenaradar.online/");return out.join("\n");}
function reportHtml(){var x=getTotals(),rows=lines.map(function(l,i){return '<tr><td>'+String(i+1)+'</td><td>'+escapeHtml(l.name)+(fields.rooms.length?'<small class="print-room-label">'+escapeHtml(roomName(l.roomId))+'</small>':'')+'</td><td>'+escapeHtml(String(l.qty)+" "+l.unit)+'</td><td>'+escapeHtml(money(l.labor))+'</td><td>'+escapeHtml(money(l.material))+'</td><td>'+escapeHtml(money(l.qty*(l.labor+l.material)))+'</td></tr>';}).join("");return '<div class="print-header"><div class="print-logo">'+(fields.pro.logo?'<img class="pro-print-logo" alt="" src="'+escapeHtml(fields.pro.logo)+'">':'CENA<span>RADAR</span>')+'</div><div class="print-right">LATVIA · 2026<br>cenaradar.online<br>'+escapeHtml(fields.number)+'</div></div><h1 class="print-title">'+escapeHtml(t("titleDoc"))+'</h1><div class="print-info"><div><strong>'+escapeHtml(t("projectName"))+'</strong>'+escapeHtml(fields.project||"—")+'</div><div><strong>'+escapeHtml(t("clientName"))+'</strong>'+escapeHtml(fields.client||"—")+'</div><div><strong>'+escapeHtml(t("estimateDate"))+'</strong>'+escapeHtml(fields.date)+'</div><div><strong>'+escapeHtml(t("estimateNr"))+'</strong>'+escapeHtml(fields.number)+'</div></div>'+proHtml()+'<table class="print-table"><thead><tr><th style="width:6%">#</th><th style="width:36%">'+escapeHtml(t("work"))+'</th><th style="width:13%">'+escapeHtml(t("qty"))+'</th><th style="width:15%">'+escapeHtml(t("labor"))+'</th><th style="width:15%">'+escapeHtml(t("materials"))+'</th><th style="width:15%">'+escapeHtml(t("sum"))+'</th></tr></thead><tbody>'+rows+'</tbody></table>'+(fields.rooms.length?'<div class="print-room-totals"><strong>'+escapeHtml(t("roomBreakdown"))+'</strong><small>'+escapeHtml(t("roomBeforeTax"))+'</small>'+roomTotals().map(function(r){return '<div><span>'+escapeHtml(r.name)+'</span><b>'+escapeHtml(money(r.total))+'</b></div>';}).join("")+'</div>':'')+'<div class="print-totals"><div><span>'+escapeHtml(t("laborCost"))+'</span><b>'+escapeHtml(money(x.labor))+'</b></div><div><span>'+escapeHtml(t("materialCost"))+'</span><b>'+escapeHtml(money(x.material))+'</b></div><div><span>'+escapeHtml(t("reserveSum"))+' ('+fields.reserve+'%)</span><b>'+escapeHtml(money(x.reserve))+'</b></div><div><span>PVN 21%</span><b>'+escapeHtml(money(x.vat))+'</b></div><div class="print-grand"><span>'+escapeHtml(t("total"))+'</span><b>'+escapeHtml(money(x.total))+'</b></div></div>'+proPaymentHtml()+(fields.notes?'<div class="print-notes"><b>'+escapeHtml(t("estimateNotes"))+'</b><p>'+escapeHtml(fields.notes)+'</p></div>':"")+signatureHtml()+'<div class="print-foot">'+(hasMissingPrice()?escapeHtml(t("quoteWarning"))+"<br>":"")+escapeHtml(t("footerDoc"))+"<br>"+escapeHtml(t("proDocNote"))+'<br>© CenaRadar · cenaradar.online</div>';}
function printEstimate(){if(!checkExport())return;$("print-sheet").innerHTML=reportHtml();window.print();}
async function shareEstimate(){if(!checkExport())return;var report=getReportText();if(navigator.share){try{await navigator.share({title:fields.project||"CenaRadar",text:report});return;}catch(e){if(e.name==="AbortError")return;}}try{await navigator.clipboard.writeText(report);toast(t("copied"));}catch(e){var ta=document.createElement("textarea");ta.value=report;document.body.appendChild(ta);ta.select();var ok=document.execCommand("copy");ta.remove();toast(ok?t("copied"):t("shareFail"));}}
function emailEstimate(){if(!checkExport())return;var body=getReportText();if(body.length>5000){body=body.slice(0,4750)+"\n...\n"+t("footerDoc");}var mail="mailto:?subject="+encodeURIComponent(t("emailSubject")+" — "+(fields.project||"CenaRadar"))+"&body="+encodeURIComponent(body);window.location.href=mail;}
function importFile(file){if(!file)return;if(file.size>2000000){toast(t("importLimit"));$("import-file").value="";return;}var reader=new FileReader();reader.onload=function(){try{var raw=JSON.parse(String(reader.result));var n=normalizeSnapshot(raw);currentId=null;fields=n.fields;lines=n.lines;fillFields();renderLines();persist();toast(t("imported"));$("estimate").scrollIntoView({behavior:"smooth"});}catch(e){toast(t("invalidFile"));}};reader.onerror=function(){toast(t("invalidFile"));};reader.readAsText(file);$("import-file").value="";}
function hasMissingPrice(){return lines.some(function(l){return l.labor===0&&works.some(function(w){return w.id===l.workId&&w.min===null;});});}
function checkExport(){if(!lines.length){toast(t("emptyEstimate"));return false;}return !hasMissingPrice()||confirm(t("incompleteConfirm"));}
async function copyEstimate(){if(!checkExport())return;var report=getReportText();try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(report);toast(t("copied"));return;}}catch(e){}var ta=document.createElement("textarea");ta.value=report;ta.style.position="fixed";ta.style.opacity="0";document.body.appendChild(ta);ta.select();var ok=false;try{ok=document.execCommand("copy");}catch(e){}ta.remove();toast(ok?t("copied"):t("shareFail"));}
