 HOUSE_NUM.forEach(function(k){$("house-"+k[0]).addEventListener("input",updateHouse);});HOUSE_CHOICES.forEach(function(k){$("house-"+k[0]).addEventListener("change",updateHouse);});HOUSE_STAGES.forEach(function(s){$("house-stage-"+s).addEventListener("change",updateHouse);});$("house-price").addEventListener("change",updateHouse);$("house-reset").addEventListener("click",function(){fields.house=defaultHouse();fillHouse();persist();});$("house-add").addEventListener("click",addHouse);document.querySelectorAll('a[href="#house-tool"]').forEach(function(a){a.addEventListener("click",function(){$("house-tool").open=true;});});
